func TestZZTsr(t *testing.T) {
	nExtra, nMissing := 0, 0
	for seed := int64(1); seed <= 400; seed++ {
		rnd := rand.New(rand.NewSource(seed))
		nRoutes := 1 + rnd.Intn(10)
		var routes []string
		root := &node{}
		for i := 0; i < nRoutes; i++ {
			p := randRoute(rnd)
			dup := false
			for _, r := range routes {
				if r == p {
					dup = true
				}
			}
			if dup {
				continue
			}
			ok := func() (ok bool) {
				defer func() {
					if rec := recover(); rec != nil {
						ok = false
					}
				}()
				root.addRoute(p, HandlersChain{func(c *Context) { fakeHandlerValue = p }})
				return true
			}()
			if ok {
				routes = append(routes, p)
			}
		}
		if len(routes) == 0 {
			continue
		}
		reMap := map[string]*regexp.Regexp{}
		for _, r := range routes {
			re, _ := routeRegexp(r)
			reMap[r] = re
		}
		matches := func(p string) bool {
			for _, r := range routes {
				if reMap[r].MatchString(p) {
					return true
				}
			}
			return false
		}
		for i := 0; i < 300; i++ {
			p := randPath(rnd)
			value := root.getValue(p, getParams(), getSkippedNodes(), false)
			if value.handlers != nil {
				continue
			}
			want := matches(p+"/") || (strings.HasSuffix(p, "/") && p != "/" && matches(strings.TrimSuffix(p, "/")))
			if value.tsr && !want {
				nExtra++
				if nExtra <= 12 {
					t.Errorf("TSREXTRA seed=%d routes=%v path=%q tsr=true but neither %q nor trimmed matches", seed, routes, p, p+"/")
				}
			}
			if !value.tsr && want {
				nMissing++
				if nMissing <= 12 {
					t.Errorf("TSRMISS seed=%d routes=%v path=%q tsr=false but variant matches", seed, routes, p)
				}
			}
		}
	}
	t.Logf("summary: tsrextra=%d tsrmiss=%d", nExtra, nMissing)
}
EOF
